    return dict(rule_id=rule_id, protocol=protocol, stage=stage, decision_point=decision_point, decision_owner=owner,
                other_actors=others, modality=modality, rule_summary_en=summary, clause_ids=clauses,
                v1_status=v1_status, correction_note=correction, attribution=attribution, accountability_trail=trail,
                interpretive_note=note)


